/**
 * image-fallback.js — generated by AWAS
 *
 * Intercepts all broken <img> tags and replaces them with a
 * local placeholder so product pages remain usable even when
 * the upstream image CDN is unavailable.
 *
 * Include this script in your base template:
 *   <script src="/static/js/image-fallback.js"></script>
 */

(function () {
  var PLACEHOLDER = '/static/images/product-placeholder.png';
  var RETRY_DELAY_MS = 3000;
  var MAX_RETRIES = 2;

  function attachFallback(img) {
    if (img.dataset.awasHandled) return;
    img.dataset.awasHandled = '1';
    img.dataset.awasRetries = '0';

    img.addEventListener('error', function onError() {
      var retries = parseInt(img.dataset.awasRetries, 10) || 0;
      if (retries < MAX_RETRIES) {
        img.dataset.awasRetries = retries + 1;
        var original = img.src;
        setTimeout(function () {
          img.src = original + (original.indexOf('?') === -1 ? '?' : '&')
            + '_awas_retry=' + Date.now();
        }, RETRY_DELAY_MS);
      } else {
        img.removeEventListener('error', onError);
        img.src = PLACEHOLDER;
        img.alt = img.alt || 'Image unavailable';
        img.style.opacity = '0.6';
      }
    });
  }

  // Attach to all existing images
  document.querySelectorAll('img').forEach(attachFallback);

  // Attach to any images added dynamically
  if (window.MutationObserver) {
    new MutationObserver(function (mutations) {
      mutations.forEach(function (m) {
        m.addedNodes.forEach(function (node) {
          if (node.tagName === 'IMG') attachFallback(node);
          if (node.querySelectorAll) {
            node.querySelectorAll('img').forEach(attachFallback);
          }
        });
      });
    }).observe(document.body, { childList: true, subtree: true });
  }
})();
